mapper.select:
SELECT
    COUNT(*) AS totalCalls,
    COALESCE(SUM(sys_ai_usage_prompt_tokens), 0) AS totalPromptTokens,
    COALESCE(SUM(sys_ai_usage_completion_tokens), 0) AS totalCompletionTokens,
    COALESCE(SUM(sys_ai_usage_total_tokens), 0) AS totalTokens,
    COALESCE(SUM(sys_ai_usage_total_cost), 0) AS totalCost,
    COALESCE(SUM(sys_ai_usage_cached_tokens), 0) AS totalCachedTokens,
    COALESCE(SUM(sys_ai_usage_original_cost), 0) AS standardCost,
    COALESCE(SUM(sys_ai_usage_total_latency), 0) AS totalLatency,
    COALESCE(SUM(sys_ai_usage_first_token_latency), 0) AS totalFirstTokenLatency
FROM sys_ai_usage

    
        AND sys_ai_usage_group_name = #{groupName}
    
    
        AND sys_ai_usage_provider = #{provider}
    
    
        AND sys_ai_usage_model = #{model}
    
    
        AND sys_ai_usage_call_time >= #{startTime}
    
    
        AND sys_ai_usage_call_time <= #{endTime}
    
    
    
        
            AND (sys_ai_usage_user_id = #{userId} OR sys_ai_usage_user_id IS NULL)
        
        
            AND sys_ai_usage_user_id = #{userId}

SELECT DATE(sys_ai_usage_call_time) AS statDate, sys_ai_usage_group_name AS groupName, sys_ai_usage_provider AS provider, sys_ai_usage_model AS model, sys_ai_usage_user_id AS userId, COUNT(*) AS totalCalls, COALESCE(SUM(sys_ai_usage_prompt_tokens), 0) AS totalPromptTokens, COALESCE(SUM(sys_ai_usage_completion_tokens), 0) AS totalCompletionTokens, COALESCE(SUM(sys_ai_usage_total_tokens), 0) AS totalTokens, COALESCE(SUM(sys_ai_usage_total_cost), 0) AS totalCost, COALESCE(SUM(sys_ai_usage_cached_tokens), 0) AS totalCachedTokens, COALESCE(SUM(sys_ai_usage_total_latency), 0) AS totalLatency, COALESCE(SUM(sys_ai_usage_first_token_latency), 0) AS totalFirstTokenLatency FROM sys_ai_usage
AND sys_ai_usage_call_time >= #{startTime}
AND sys_ai_usage_call_time < #{endTime}
AND (sys_ai_usage_user_id = #{userId} OR sys_ai_usage_user_id IS NULL)
AND sys_ai_usage_user_id = #{userId}
GROUP BY DATE(sys_ai_usage_call_time), sys_ai_usage_group_name, sys_ai_usage_provider, sys_ai_usage_model, sys_ai_usage_user_id ORDER BY statDate

SELECT DATE_FORMAT(sys_ai_usage_call_time, '%Y-%m-%d %H:00') AS statHour, COUNT(*) AS totalCalls, COALESCE(SUM(sys_ai_usage_prompt_tokens), 0) AS totalPromptTokens, COALESCE(SUM(sys_ai_usage_completion_tokens), 0) AS totalCompletionTokens, COALESCE(SUM(sys_ai_usage_total_tokens), 0) AS totalTokens, COALESCE(SUM(sys_ai_usage_total_cost), 0) AS totalCost, COALESCE(SUM(sys_ai_usage_cached_tokens), 0) AS totalCachedTokens FROM sys_ai_usage
AND sys_ai_usage_call_time >= #{startTime}
AND sys_ai_usage_call_time < #{endTime}
AND (sys_ai_usage_user_id = #{userId} OR sys_ai_usage_user_id IS NULL)
AND sys_ai_usage_user_id = #{userId}
GROUP BY statHour ORDER BY statHour

SELECT sys_ai_usage_group_name AS groupName, sys_ai_usage_provider AS provider, sys_ai_usage_model AS model, COUNT(*) AS totalCalls, COALESCE(SUM(sys_ai_usage_prompt_tokens), 0) AS totalPromptTokens, COALESCE(SUM(sys_ai_usage_completion_tokens), 0) AS totalCompletionTokens, COALESCE(SUM(sys_ai_usage_total_tokens), 0) AS totalTokens, COALESCE(SUM(sys_ai_usage_total_cost), 0) AS totalCost FROM sys_ai_usage
AND sys_ai_usage_model = #{model}
AND sys_ai_usage_call_time >= #{startTime}
AND sys_ai_usage_call_time <= #{endTime}
AND (sys_ai_usage_user_id = #{userId} OR sys_ai_usage_user_id IS NULL)
AND sys_ai_usage_user_id = #{userId}
GROUP BY sys_ai_usage_group_name, sys_ai_usage_provider, sys_ai_usage_model ORDER BY totalTokens DESC

SELECT DATE(sys_ai_usage_call_time) AS statDate, sys_ai_usage_provider AS provider, sys_ai_usage_model AS model, COUNT(*) AS totalCalls, COALESCE(SUM(sys_ai_usage_total_tokens), 0) AS totalTokens, COALESCE(SUM(sys_ai_usage_total_cost), 0) AS totalCost,
AVG(sys_ai_usage_first_token_latency) AS avgFirstTokenLatency, AVG(sys_ai_usage_total_latency) AS avgTotalLatency FROM sys_ai_usage
AND sys_ai_usage_call_time >= #{startTime}
AND sys_ai_usage_call_time < #{endTime}
AND (sys_ai_usage_user_id = #{userId} OR sys_ai_usage_user_id IS NULL)
AND sys_ai_usage_user_id = #{userId}
GROUP BY DATE(sys_ai_usage_call_time), sys_ai_usage_provider, sys_ai_usage_model ORDER BY statDate, totalTokens DESC

SELECT sys_ai_usage_provider AS provider, sys_ai_usage_model AS model, AVG(sys_ai_usage_tokens_per_second) AS avgSpeedTps FROM sys_ai_usage
AND sys_ai_usage_provider = #{provider}
AND sys_ai_usage_model = #{model}
AND sys_ai_usage_tokens_per_second IS NOT NULL
GROUP BY sys_ai_usage_provider, sys_ai_usage_model
